const TETRIS_ELEMENTS={gi:[['anemo','/assets/genshin/elements/gi-anemo.png','#75d6ae'],['cryo','/assets/genshin/elements/gi-cryo.png','#9fe9f0'],['geo','/assets/genshin/elements/gi-geo.png','#e6b75e'],['electro','/assets/genshin/elements/gi-electro.png','#c19af3'],['dendro','/assets/genshin/elements/gi-dendro.png','#9ddc62'],['hydro','/assets/genshin/elements/gi-hydro.png','#63c7f5'],['pyro','/assets/genshin/elements/gi-pyro.png','#ff916b']],hsr:[['wind','/assets/elements/hsr-wind.png','#75d6ae'],['ice','/assets/elements/hsr-ice.png','#9fe9f0'],['physical','/assets/elements/hsr-physical.png','#e6b75e'],['thunder','/assets/elements/hsr-thunder.png','#c19af3'],['imaginary','/assets/elements/hsr-imaginary.png','#e8ca75'],['quantum','/assets/elements/hsr-quantum.png','#bc8df0'],['fire','/assets/elements/hsr-fire.png','#ff916b']],ww:[['aero','/assets/elements/ww-aero.svg','#69d5ae'],['glacio','/assets/elements/ww-glacio.svg','#a8e8f2'],['fusion','/assets/elements/ww-fusion.svg','#ff8a66'],['electro','/assets/elements/ww-electro.svg','#c58bfa'],['havoc','/assets/elements/ww-havoc.svg','#ed75ad'],['spectro','/assets/elements/ww-spectro.svg','#f6d779']]};
