function arcadeElementIcon(game,character,kind){
  const value=String(character?.elementText||character?.element||character?.pathText||character?.path||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const candidates=TETRIS_ELEMENTS[game]||TETRIS_ELEMENTS.gi;
  const element=candidates.find(([key])=>value.includes(key))||candidates[kind%candidates.length];
  return {icon:element[1],color:element[2],label:element[0]};
}

