    'jing yuan':{title:'Seigneur fulgurant',detail:'Tous les trois dégagements, un éclair balaie une colonne.',kind:'lightning',visual:'lightning',value:3},
    'fu xuan':{title:'Matrice de prescience',detail:'La préscience accorde un bouclier contre une collision fatale.',kind:'shield',visual:'quantum',value:1},
    acheron:{title:'Éclat de la pluie rouge',detail:'Après trois lignes cumulées, son éclair efface une colonne.',kind:'lightning',visual:'lightning',value:3},
